31	 * Returns an interactive Container with hover/press feedback.
32	 */
33	export interface ButtonOptions {
34	  x: number;
35	  y: number;
36	  onClick: () => void;
37	  /** Background texture key. If omitted, a rectangle is drawn instead. */
38	  texture?: string;
39	  /** Centered label text. */
40	  label?: string;
41	  /** Explicit hit size; defaults to the texture size, or 220×64 for the rect. */
42	  width?: number;
43	  height?: number;
44	  /** Overrides merged onto the default label text style. */
45	  labelStyle?: Phaser.Types.GameObjects.Text.TextStyle;
46	}
