57	
58	  let width = opts.width ?? 0;
59	  let height = opts.height ?? 0;
60	
61	  if (opts.texture) {
62	    const bg = scene.add.image(0, 0, opts.texture).setOrigin(0.5);
63	    width = width || bg.width;
64	    height = height || bg.height;
65	    container.add(bg);
66	  } else {
67	    width = width || 220;
68	    height = height || 64;
69	    const rect = scene.add
70	      .rectangle(0, 0, width, height, 0x2b3a46)
71	      .setStrokeStyle(2, 0x5b6670)
72	      .setOrigin(0.5);
73	    container.add(rect);
74	  }
75	
76	  if (opts.label !== undefined) {
77	    const style: Phaser.Types.GameObjects.Text.TextStyle = { ...DEFAULT_LABEL_STYLE, ...opts.labelStyle };
78	    const text = scene.add.text(0, 0, opts.label, style).setOrigin(0.5);
79	    container.add(text);
80	  }
81	
82	  // The hit area is the VISIBLE art, expanded to a comfortable minimum tap target
83	  // on each axis (never smaller). The SVG is rasterized to its manifest size, so
84	  // bg.width/height == the displayed frame; the art fills that frame (only a few
85	  // px of transparent padding), so a frame-sized-or-larger rect covers the whole
86	  // visible button. The rect is in the container's local space and Phaser applies
87	  // the container transform during hit-testing, so the press/hover SCALE never
88	  // shifts the effective hit region off the button.
89	  const hitW = Math.max(width, MIN_TAP_TARGET_PX);
