93	    new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
94	    Phaser.Geom.Rectangle.Contains,
95	  );
96	  if (container.input) {
97	    container.input.cursor = 'pointer';
98	  }
