104	  // a tap, so returning to the hover scale would leave the control stuck enlarged
105	  // — snap back to 1; on mouse, keep the hover scale since the cursor is still on
106	  // the button. POINTER_OUT already handles press-then-drag-off (→ scale 1).
107	  container.on(Phaser.Input.Events.POINTER_UP, (pointer: Phaser.Input.Pointer) => {
108	    container.setScale(pointer.wasTouch ? 1 : HOVER_SCALE);
109	    opts.onClick();
110	  });
111	
112	  return container;
