1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT, MIN_TAP_TARGET_PX, PROMO_COPY_FADE_MS } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { track, type FinishGameParams } from '../analytics/track';
7	import { createButton } from '../ui/Button';
8	import { ENV, buildBuyUrl, buyDestination } from '../config/env';
9	import { playSfx, Sfx, stopMusic } from '../systems/audio';
10	
11	/**
12	 * ResultsScene — Victory or Game Over depending on the `result` param, the final
13	 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
14	 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
15	 */
16	export class ResultsScene extends Phaser.Scene {
17	  constructor() {
18	    super({ key: SceneKey.Results });
19	  }
20	
21	  create(data: Partial<FinishGameParams> = {}): void {
22	    // Robust if entered without/with partial data (e.g. deep-link, hot reload):
23	    // default to a Game-Over result and a zero score.
24	    const win = data.result === 'win';
25	    const score = typeof data.score === 'number' ? data.score : 0;
26	    const cx = GAME_WIDTH / 2;
27	
28	    // The gameplay loop already stops its music on run-end; this is a defensive
29	    // stop for any entry path (deep-link / hot reload) so Results is silent.
30	    stopMusic();
31	
32	    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
33	    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);
34	
35	    this.add
36	      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
37	        fontFamily: 'system-ui, sans-serif',
38	        fontSize: '48px',
39	        fontStyle: 'bold',
40	        color: '#20272e',
41	      })
42	      .setOrigin(0.5);
43	
44	    this.add
45	      .text(cx, 380, t('results_score', { score }), {
46	        fontFamily: 'system-ui, sans-serif',
47	        fontSize: '30px',
48	        color: '#20272e',
49	      })
50	      .setOrigin(0.5);
51	
52	    // Promo chip + code (tap-to-copy).
53	    this.buildPromoCopyChip(cx, 460);
54	
55	    // The conversion CTA.
56	    createButton(this, {
57	      x: cx,
58	      y: 565,
59	      texture: KEYS.ui_btn_cta,
60	      label: t('results_cta'),
61	      onClick: () => this.onBuy(),
62	    });
63	
64	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
65	    createButton(this, {
66	      x: cx,
67	      y: 660,
68	      texture: KEYS.ui_btn_play_again,
69	      label: t('results_play_again'),
70	      onClick: () => {
71	        playSfx(this, Sfx.ui);
72	        this.scene.start(SceneKey.Game);
73	      },
74	    });
75	
76	    // Tertiary: back to the menu — closes the Boot→…→Results→Menu loop. The
77	    // vertical padding grows the tap target to ~48px tall for touch a11y (§10.4).
78	    this.add
79	      .text(90, 44, `← ${t('results_menu')}`, {
80	        fontFamily: 'system-ui, sans-serif',
81	        fontSize: '22px',
82	        color: '#20272e',
83	        padding: { y: 12 },
84	      })
85	      .setOrigin(0, 0.5)
86	      .setInteractive({ useHandCursor: true })
87	      .on(Phaser.Input.Events.POINTER_UP, () => {
88	        playSfx(this, Sfx.ui);
89	        this.scene.start(SceneKey.Menu);
90	      });
91	  }
92	
93	  private buildPromoCopyChip(x: number, y: number): void {
94	    const container = this.add.container(x, y);
95	    const chip = this.add.image(0, 0, KEYS.ui_promo_chip).setOrigin(0.5);
96	    const text = this.add
97	      .text(0, 0, `${t('results_promo_label')} ${ENV.promoCode}`, {
98	        fontFamily: 'monospace',
99	        fontSize: '26px',
100	        fontStyle: 'bold',
101	        color: '#20272e',
102	      })
103	      .setOrigin(0.5);
104	    container.add([chip, text]);
105	    // Match the hit area to the ACTUAL chip art (460×120) — the old 400×100 left
106	    // the pill's outer edges dead — floored to the comfortable tap target.
107	    const hitW = Math.max(chip.width, MIN_TAP_TARGET_PX);
108	    const hitH = Math.max(chip.height, MIN_TAP_TARGET_PX);
109	    container.setSize(hitW, hitH);
110	    container.setInteractive(
111	      new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
112	      Phaser.Geom.Rectangle.Contains,
113	    );
114	    if (container.input) container.input.cursor = 'pointer';
115	    container.on(Phaser.Input.Events.POINTER_UP, () => this.copyPromoCode());
116	  }
117	
118	  private async copyPromoCode(): Promise<void> {
119	    try {
120	      if (!navigator.clipboard) {
121	        return; // feature unavailable, silent no-op
122	      }
123	      await navigator.clipboard.writeText(ENV.promoCode);
124	      playSfx(this, Sfx.ui);
125	      this.showCopyConfirmation();
126	    } catch {
127	      // copy failed (e.g., no permission), silent no-op
128	      return;
129	    }
130	  }
131	
132	  private showCopyConfirmation(): void {
133	    const cx = GAME_WIDTH / 2;
134	    const label = this.add
135	      .text(cx, 410, t('results_promo_copied'), {
136	        fontFamily: 'system-ui, sans-serif',
137	        fontSize: '16px',
138	        fontStyle: 'bold',
139	        color: '#6cc04a',
140	      })
141	      .setOrigin(0.5)
142	      .setAlpha(1);
143	    this.tweens.add({
144	      targets: label,
145	      alpha: 0,
146	      duration: PROMO_COPY_FADE_MS,
147	      ease: 'Quad.in',
148	      onComplete: () => label.destroy(),
149	    });
150	  }
151	
152	  private onBuy(): void {
153	    playSfx(this, Sfx.ui);
154	    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
155	    window.open(buildBuyUrl(), '_blank', 'noopener');
156	  }
157	}
